/**
 * Cookie consent. Nothing is stored on the device until the visitor accepts.
 * The banner is only shown when they change the theme. Accepting allows
 * everything (saved theme + Google Analytics cookies); declining stores nothing
 * and the theme change lasts until the page reloads.
 *
 * index.html / homepage.html apply the same key before gtag.js loads
 * (GA consent default + clean-up), keep them in sync.
 */

const CONSENT_KEY = 'edb-cookie-consent';
export const THEME_STORAGE_KEY = 'edb-theme';

const read = (key) => {
  try { return window.localStorage.getItem(key); } catch { return null; }
};
const write = (key, value) => {
  try {
    if (value === null) window.localStorage.removeItem(key);
    else window.localStorage.setItem(key, value);
  } catch { /* storage blocked */ }
};

export const hasConsent = () => typeof window !== 'undefined' && read(CONSENT_KEY) === 'accepted';

export function readStoredTheme() {
  if (!hasConsent()) return null;
  const stored = read(THEME_STORAGE_KEY);
  return stored === 'light' || stored === 'dark' ? stored : null;
}

function deleteAnalyticsCookies() {
  const parts = window.location.hostname.split('.');
  document.cookie.split(';').forEach((cookie) => {
    const name = cookie.split('=')[0].trim();
    if (!/^(_ga|_gid|_gat)/.test(name)) return;
    const expire = `${name}=; Max-Age=0; path=/`;
    document.cookie = expire;
    for (let i = 0; i < parts.length - 1; i += 1) {
      document.cookie = `${expire}; domain=.${parts.slice(i).join('.')}`;
    }
  });
}

// In-memory only, never persisted.
let sessionTheme = null;
let declinedThisPage = false;
const listeners = new Set();

/** Subscribe to banner requests; the callback gets the banner copy to show. */
export function onConsentRequest(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function requestConsent(reason = 'default') {
  listeners.forEach((listener) => listener(reason));
}

/** Called after every manual theme toggle. */
export function rememberTheme(theme) {
  sessionTheme = theme;
  if (hasConsent()) { write(THEME_STORAGE_KEY, theme); return; }
  if (!declinedThisPage) requestConsent('default');
}

export function acceptConsent() {
  write(CONSENT_KEY, 'accepted');
  if (sessionTheme) write(THEME_STORAGE_KEY, sessionTheme);
  if (typeof window.gtag === 'function') window.gtag('consent', 'update', { analytics_storage: 'granted' });
}

export function declineConsent() {
  declinedThisPage = true;
  write(CONSENT_KEY, null);
  write(THEME_STORAGE_KEY, null);
  if (typeof window.gtag === 'function') window.gtag('consent', 'update', { analytics_storage: 'denied' });
  deleteAnalyticsCookies();
}

/** Closed with the X: store nothing, don't ask again until reload. */
export function dismissConsent() {
  declinedThisPage = true;
}
